-- Generated by Ingestron from flows/crm.yaml (table orders). Do not edit: change the definitions and generate again.
-- Changes as received, each read once.
CREATE OR REFRESH STREAMING TABLE `bronze`.`orders_changes`
AS SELECT * FROM STREAM read_files(
  '${ingestron.crm_path}/orders',
  format => 'parquet',
  schemaHints => '`id` BIGINT, `customer_id` BIGINT, `status` STRING, `total` DECIMAL(18,2), `updated_at` TIMESTAMP',
  schemaEvolutionMode => 'addNewColumns'
);

-- The current rows, kept by key.
CREATE OR REFRESH STREAMING TABLE `bronze`.`orders` (
  CONSTRAINT `id_not_null` EXPECT (`id` IS NOT NULL),
  CONSTRAINT `customer_id_not_null` EXPECT (`customer_id` IS NOT NULL),
  CONSTRAINT `updated_at_not_null` EXPECT (`updated_at` IS NOT NULL)
)
COMMENT 'One row per order, kept current.'
CLUSTER BY AUTO;

CREATE FLOW `orders_cdc`
AS AUTO CDC INTO `bronze`.`orders`
FROM STREAM(`bronze`.`orders_changes`)
KEYS (`id`)
SEQUENCE BY `updated_at`
STORED AS SCD TYPE 1;
